export default {"file":"admin-dashboard.html","title":"Schoolix - Admin Dashboard","htmlClass":"","bodyClass":"sx-admin-app","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n<div id=\"sx-page-root\">\r\n<div class=\"page-wrap\">\r\n\r\n    <!-- ── TOP BAR (logout) ──────────────────────── -->\r\n    <!-- ── HERO / SCHOOL NAME ────────────────────── -->\r\n    <div class=\"hero\">\r\n        <div class=\"hero-badge\">\r\n            <i class=\"fas fa-shield-alt\"></i>\r\n            Admin Workspace\r\n        </div>\r\n        <div class=\"school-name\" id=\"schoolDisplayName\">\r\n            <span>Schoolix</span>\r\n        </div>\r\n        <div class=\"school-owner\" id=\"schoolTagline\">Panel owner will appear here</div>\r\n    </div>\r\n\r\n    <!-- ── WELCOME BANNER ────────────────────────── -->\r\n    <div class=\"user-welcome\" id=\"userWelcome\">\r\n        <div class=\"welcome-avatar\">\r\n            <i class=\"fas fa-user-tie\"></i>\r\n        </div>\r\n        <div class=\"welcome-text\">\r\n            <div class=\"welcome-title\">Welcome back, <span id=\"userName\"></span></div>\r\n            <div class=\"welcome-subtitle\" id=\"userEmail\"></div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- ── STATS ──────────────────────────────────── -->\r\n    <div class=\"stats-bar\">\r\n        <div class=\"stat-item\">\r\n            <div class=\"stat-icon\"><i class=\"fas fa-users\"></i> Students</div>\r\n            <span class=\"stat-number\" id=\"totalStudents\">Loading</span>\r\n        </div>\r\n        <div class=\"stat-item\">\r\n            <div class=\"stat-icon\"><i class=\"fas fa-layer-group\"></i> Class Sections</div>\r\n            <span class=\"stat-number\" id=\"totalClasses\">Loading</span>\r\n        </div>\r\n        <div class=\"stat-item\">\r\n            <div class=\"stat-icon\"><i class=\"fas fa-chalkboard-teacher\"></i> Teachers</div>\r\n            <span class=\"stat-number\" id=\"totalTeachers\">Loading</span>\r\n        </div>\r\n        <div class=\"stat-item\">\r\n            <div class=\"stat-icon\"><i class=\"fas fa-rupee-sign\"></i> Collected Fees</div>\r\n            <span class=\"stat-number\" id=\"totalFees\">Loading</span>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- ── DASHBOARD GRID ────────────────────────── -->\r\n    <div class=\"section-label\">Quick Access</div>\r\n    <div class=\"dashboard-grid\">\r\n\r\n        <a href=\"#/add-student.html\" class=\"card students\" title=\"Add New Students\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-user-plus\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Add Students</div>\r\n                <div class=\"card-subtitle\">Enroll new student</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/students.html\" class=\"card students\" title=\"View All Students\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-users\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">View Students</div>\r\n                <div class=\"card-subtitle\">Browse all records</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"passed-out-#/students.html\" class=\"card students\" title=\"Passed Out Students\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-user-graduate\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Passed Out</div>\r\n                <div class=\"card-subtitle\">Year-wise archive</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/teachers.html\" class=\"card teacher\" title=\"Manage teachers, attendance and salary\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-chalkboard-teacher\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Manage Teachers</div>\r\n                <div class=\"card-subtitle\">Attendance & salary</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"subjects.html\" class=\"card reports\" title=\"Manage school subjects\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-book-open\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Manage Subjects</div>\r\n                <div class=\"card-subtitle\">School subject catalogue</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/staff-management.html\" class=\"card staff\" title=\"Manage all staff accounts\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-users-gear\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Staff Management</div>\r\n                <div class=\"card-subtitle\">Teachers, librarian & accounts</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/generate-tc.html\" class=\"card tc\" title=\"Generate Transfer Certificate\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-file-signature\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Generate TC</div>\r\n                <div class=\"card-subtitle\">Transfer certificate</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/reportcards.html\" class=\"card reports\" title=\"Generate Report Cards\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-chart-line\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Report Cards</div>\r\n                <div class=\"card-subtitle\">Generate & print</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/fees-report.html\" class=\"card fees\" title=\"Fees Management\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-rupee-sign\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Fees Report</div>\r\n                <div class=\"card-subtitle\">Payments & dues</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/school-accounts.html\" class=\"card accounts\" title=\"Manage school income and expenses\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-book\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Accounts Management</div>\r\n                <div class=\"card-subtitle\">Credits, debits & balance</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/notifications.html\" class=\"card notifications\" title=\"Push app notification\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-bell\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Push Notification</div>\r\n                <div class=\"card-subtitle\">Notify teachers & students</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/notices.html\" class=\"card notifications\" title=\"Create school notices\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-bullhorn\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Notices</div>\r\n                <div class=\"card-subtitle\">Text, PDF & app alerts</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/accountant-management.html\" class=\"card accountant\" title=\"Add accountant login\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-user-tie\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Add Accountant</div>\r\n                <div class=\"card-subtitle\">Portal login & accounts</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/library-management.html\" class=\"card library\" title=\"Library Management\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-book-open\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Library</div>\r\n                <div class=\"card-subtitle\">Books & librarian</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n        <a href=\"#/vehicle-management.html\" class=\"card vehicle\" title=\"Vehicle Management\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-bus\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Vehicle Management</div>\r\n                <div class=\"card-subtitle\">Routes & transport</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n\r\n       \r\n\r\n        <a href=\"#/admin-timetable.html\" class=\"card timetable\" title=\"Manage Timetables\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-calendar-alt\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Timetable</div>\r\n                <div class=\"card-subtitle\">Schedule & periods</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n <a href=\"#/additional-settings.html\" class=\"card settings\" title=\"Additional Settings\">\r\n            <div class=\"card-icon\"><i class=\"fas fa-cog\"></i></div>\r\n            <div class=\"card-text\">\r\n                <div class=\"card-title\">Additional Settings</div>\r\n                <div class=\"card-subtitle\">System preferences</div>\r\n            </div>\r\n            <i class=\"fas fa-chevron-right card-arrow\"></i>\r\n        </a>\r\n    </div>\r\n\r\n    <!-- ── LOGIN SECTION ─────────────────────────── -->\r\n    <div class=\"login-section\" id=\"loginSection\">\r\n        <button class=\"btn-primary pulse\" onclick=\"loginWithGoogle()\">\r\n            <i class=\"fab fa-google\"></i>\r\n            Sign in with Google\r\n        </button>\r\n        <div class=\"features-text\">\r\n            Secure access · Cloud sync · Fast performance · Responsive layout\r\n        </div>\r\n    </div>\r\n\r\n</div><!-- /page-wrap -->\r\n</div><!-- /sx-page-root -->\r\n\r\n<div class=\"sx-first-login-launch\" id=\"firstLoginLaunch\" aria-hidden=\"true\">\r\n    <div class=\"sx-launch-stage\">\r\n        <div class=\"sx-launch-logo\" id=\"firstLoginLaunchLogo\">\r\n            <img src=\"schoolix-app-icon.svg\" alt=\"Schoolix\">\r\n        </div>\r\n        <div class=\"sx-launch-title\">Welcome to Schoolix</div>\r\n        <div class=\"sx-launch-copy\" id=\"firstLoginLaunchCopy\">Preparing your school workspace...</div>\r\n        <div class=\"sx-launch-steps\" aria-hidden=\"true\"><span></span><span></span><span></span></div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\"sx-first-setup-overlay\" id=\"firstSetupOverlay\" aria-hidden=\"true\">\r\n    <section class=\"sx-setup-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"firstSetupTitle\">\r\n        <div class=\"sx-setup-head\">\r\n            <div class=\"sx-setup-eyebrow\">First time setup</div>\r\n            <h2 id=\"firstSetupTitle\">Set up your school year</h2>\r\n            <p>Save the active academic session now. These basics keep students, fees, reports and attendance aligned from day one.</p>\r\n        </div>\r\n        <form class=\"sx-setup-body\" id=\"firstSetupForm\">\r\n            <div class=\"sx-setup-grid\">\r\n                <div class=\"sx-setup-field\">\r\n                    <label for=\"setupStartYear\">Session start year</label>\r\n                    <input type=\"number\" id=\"setupStartYear\" min=\"2000\" max=\"2100\" required>\r\n                </div>\r\n                <div class=\"sx-setup-field\">\r\n                    <label for=\"setupEndYear\">Session end year</label>\r\n                    <input type=\"number\" id=\"setupEndYear\" min=\"2001\" max=\"2101\" required>\r\n                </div>\r\n                <div class=\"sx-setup-field\">\r\n                    <label for=\"setupSchoolPhone\">School phone</label>\r\n                    <input type=\"tel\" id=\"setupSchoolPhone\" placeholder=\"Optional\">\r\n                </div>\r\n                <div class=\"sx-setup-field\">\r\n                    <label for=\"setupSchoolCode\">School code</label>\r\n                    <input type=\"text\" id=\"setupSchoolCode\" placeholder=\"Optional\">\r\n                </div>\r\n                <div class=\"sx-setup-field full\">\r\n                    <label for=\"setupSchoolAddress\">School address</label>\r\n                    <textarea id=\"setupSchoolAddress\" placeholder=\"Optional\"></textarea>\r\n                </div>\r\n            </div>\r\n            <div class=\"sx-setup-actions\">\r\n                <div class=\"sx-setup-status\" id=\"firstSetupStatus\">This window appears only for this admin's first login.</div>\r\n                <button type=\"submit\" class=\"sx-setup-save\" id=\"firstSetupSaveBtn\">\r\n                    <i class=\"fas fa-check\"></i> Save & enter dashboard\r\n                </button>\r\n            </div>\r\n        </form>\r\n    </section>\r\n</div>\r\n\r\n    <script src=\"school-branding.js\"></script>\r\n    <script type=\"module\">\r\n        import { initializeApp } from \"./firebase-compat.js\";\r\n        import { \r\n            getAuth, \r\n            signInWithPopup, \r\n            GoogleAuthProvider, \r\n            signOut,\r\n            onAuthStateChanged\r\n        } from \"./firebase-compat.js\";\r\n        import { \r\n            getFirestore\r\n        } from \"./firebase-compat.js\";\r\n        import {\r\n            doc,\r\n            getDoc,\r\n            setDoc,\r\n            updateDoc,\r\n            collection,\r\n            getDocs,\r\n            query,\r\n            where,\r\n            serverTimestamp\r\n        } from \"./firebase-compat.js\";\r\n\r\n        const firebaseConfig = {\r\n            apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n            authDomain: \"schoolix-48107.firebaseapp.com\",\r\n            projectId: \"schoolix-48107\",\r\n            storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n            messagingSenderId: \"133937954491\",\r\n            appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n            measurementId: \"G-EG23XE5Q0Z\"\r\n        };\r\n\r\n        const app = initializeApp(firebaseConfig);\r\n        const auth = getAuth(app);\r\n        const db = getFirestore(app);\r\n        const provider = new GoogleAuthProvider();\r\n\r\n        const userWelcome = document.getElementById('userWelcome');\r\n        const userNameEl = document.getElementById('userName');\r\n        const userEmailEl = document.getElementById('userEmail');\r\n        const loginSection = document.getElementById('loginSection');\r\n        const schoolDisplayNameEl = document.getElementById('schoolDisplayName');\r\n        const schoolTaglineEl = document.getElementById('schoolTagline');\r\n        const firstLoginLaunch = document.getElementById('firstLoginLaunch');\r\n        const firstLoginLaunchCopy = document.getElementById('firstLoginLaunchCopy');\r\n        const firstLoginLaunchLogo = document.getElementById('firstLoginLaunchLogo');\r\n        const firstSetupOverlay = document.getElementById('firstSetupOverlay');\r\n        const firstSetupForm = document.getElementById('firstSetupForm');\r\n        const firstSetupStatus = document.getElementById('firstSetupStatus');\r\n        const firstSetupSaveBtn = document.getElementById('firstSetupSaveBtn');\r\n        const dashboardStatsCachePrefix = 'schoolix.dashboardStats.v1.';\r\n        const dashboardStatsCacheTtl = 5 * 60 * 1000;\r\n        let onboardingUser = null;\r\n        let onboardingProfile = null;\r\n\r\n        function formatCurrency(value) {\r\n            return `₹${Math.round(Number(value || 0)).toLocaleString('en-IN')}`;\r\n        }\r\n\r\n        async function loadAdminProfile(user) {\r\n            try {\r\n                const userSnap = await getDoc(doc(db, \"users\", user.uid));\r\n                if (!userSnap.exists()) return null;\r\n\r\n                const adminData = userSnap.data();\r\n                const schoolName = adminData.schoolName || window.SchoolBranding?.getSchoolName() || \"Schoolix\";\r\n                window.SchoolBranding?.persistSchoolLogo?.(adminData.logoUrl || adminData.schoolLogoUrl || \"\");\r\n                const adminName = adminData.name || user.displayName || user.email.split('@')[0];\r\n\r\n                window.SchoolBranding?.persistSchoolName(schoolName);\r\n                schoolDisplayNameEl.innerHTML = `<span>${schoolName}</span>`;\r\n                schoolTaglineEl.textContent = `Panel Owner: ${adminName}`;\r\n                userNameEl.textContent = adminName;\r\n                userEmailEl.textContent = `${schoolName} · ${user.email}`;\r\n\r\n                return { ...adminData, schoolName, adminName };\r\n            } catch (error) {\r\n                console.error(\"Admin profile load error:\", error);\r\n                return null;\r\n            }\r\n        }\r\n\r\n        function escapeAttribute(value) {\r\n            return String(value || \"\").replace(/&/g, \"&amp;\").replace(/\"/g, \"&quot;\").replace(/</g, \"&lt;\");\r\n        }\r\n\r\n        function suggestAcademicYears() {\r\n            const now = new Date();\r\n            const start = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;\r\n            return { start, end: start + 1 };\r\n        }\r\n\r\n        function getOnboardingStorageKey(userId) {\r\n            return `schoolix.adminOnboardingDone.${userId}`;\r\n        }\r\n\r\n        function needsFirstSetup(user, adminData) {\r\n            if (!user || String(adminData?.role || \"\").toLowerCase() !== \"admin\") return false;\r\n            if (adminData?.onboardingRequired !== true) return false;\r\n            try {\r\n                if (localStorage.getItem(getOnboardingStorageKey(user.uid)) === \"true\") return false;\r\n            } catch (_) {}\r\n            return adminData?.onboardingCompleted !== true && !adminData?.onboardingCompletedAt;\r\n        }\r\n\r\n        function primeSetupForm(adminData = {}) {\r\n            const years = suggestAcademicYears();\r\n            document.getElementById(\"setupStartYear\").value = adminData.setup?.sessionStartYear || years.start;\r\n            document.getElementById(\"setupEndYear\").value = adminData.setup?.sessionEndYear || years.end;\r\n            document.getElementById(\"setupSchoolPhone\").value = adminData.schoolPhone || adminData.phone || \"\";\r\n            document.getElementById(\"setupSchoolCode\").value = adminData.schoolCode || \"\";\r\n            document.getElementById(\"setupSchoolAddress\").value = adminData.schoolAddress || adminData.address || \"\";\r\n        }\r\n\r\n        async function runFirstLoginOnboarding(user, adminData) {\r\n            if (!needsFirstSetup(user, adminData)) return;\r\n            onboardingUser = user;\r\n            onboardingProfile = adminData || {};\r\n            primeSetupForm(onboardingProfile);\r\n            firstLoginLaunchCopy.textContent = `Preparing ${onboardingProfile.schoolName || \"your school\"} workspace...`;\r\n            const logoUrl = onboardingProfile.logoUrl || onboardingProfile.schoolLogoUrl || \"\";\r\n            firstLoginLaunchLogo.innerHTML = logoUrl\r\n                ? `<img src=\"${escapeAttribute(logoUrl)}\" alt=\"School logo\">`\r\n                : `<img src=\"schoolix-app-icon.svg\" alt=\"Schoolix\">`;\r\n            firstLoginLaunch.classList.add(\"is-visible\");\r\n            firstLoginLaunch.setAttribute(\"aria-hidden\", \"false\");\r\n            window.setTimeout(() => {\r\n                firstLoginLaunch.classList.remove(\"is-visible\");\r\n                firstLoginLaunch.setAttribute(\"aria-hidden\", \"true\");\r\n                firstSetupOverlay.classList.add(\"is-visible\");\r\n                firstSetupOverlay.setAttribute(\"aria-hidden\", \"false\");\r\n                document.getElementById(\"setupStartYear\")?.focus();\r\n            }, 2050);\r\n        }\r\n\r\n        function setSetupStatus(message, type = \"\") {\r\n            firstSetupStatus.textContent = message;\r\n            firstSetupStatus.className = `sx-setup-status ${type}`.trim();\r\n        }\r\n\r\n        firstSetupForm.addEventListener(\"submit\", async (event) => {\r\n            event.preventDefault();\r\n            if (!onboardingUser) return;\r\n            const startYear = Number(document.getElementById(\"setupStartYear\").value);\r\n            const endYear = Number(document.getElementById(\"setupEndYear\").value);\r\n            const schoolPhone = document.getElementById(\"setupSchoolPhone\").value.trim();\r\n            const schoolCode = document.getElementById(\"setupSchoolCode\").value.trim();\r\n            const schoolAddress = document.getElementById(\"setupSchoolAddress\").value.trim();\r\n            if (!startYear || !endYear || endYear <= startYear) {\r\n                setSetupStatus(\"Please enter a valid academic session.\", \"error\");\r\n                return;\r\n            }\r\n            const sessionLabel = `${startYear}-${endYear}`;\r\n            const sessionId = sessionLabel.replace(/[^0-9a-zA-Z]+/g, \"-\").replace(/^-+|-+$/g, \"\");\r\n            firstSetupSaveBtn.disabled = true;\r\n            setSetupStatus(\"Saving setup...\");\r\n            try {\r\n                await setDoc(doc(db, \"schools\", onboardingUser.uid, \"sessions\", sessionId), {\r\n                    startYear,\r\n                    endYear,\r\n                    session: sessionLabel,\r\n                    locked: false,\r\n                    classesLocked: false,\r\n                    createdAt: serverTimestamp(),\r\n                    createdBy: onboardingUser.uid,\r\n                    createdFrom: \"first-login-setup\"\r\n                }, { merge: true });\r\n\r\n                await setDoc(doc(db, \"schools\", onboardingUser.uid, \"settings\", \"activeSession\"), {\r\n                    sessionId,\r\n                    session: sessionLabel,\r\n                    sessionLabel,\r\n                    updatedAt: serverTimestamp(),\r\n                    updatedBy: onboardingUser.uid\r\n                }, { merge: true });\r\n\r\n                const setupPayload = {\r\n                    onboardingRequired: false,\r\n                    onboardingCompleted: true,\r\n                    onboardingCompletedAt: serverTimestamp(),\r\n                    setup: {\r\n                        sessionId,\r\n                        session: sessionLabel,\r\n                        sessionStartYear: startYear,\r\n                        sessionEndYear: endYear,\r\n                        completedAt: new Date().toISOString()\r\n                    },\r\n                    updatedAt: serverTimestamp()\r\n                };\r\n                if (schoolPhone) setupPayload.schoolPhone = schoolPhone;\r\n                if (schoolCode) setupPayload.schoolCode = schoolCode;\r\n                if (schoolAddress) setupPayload.schoolAddress = schoolAddress;\r\n\r\n                await Promise.all([\r\n                    updateDoc(doc(db, \"users\", onboardingUser.uid), setupPayload),\r\n                    setDoc(doc(db, \"schools\", onboardingUser.uid), setupPayload, { merge: true })\r\n                ]);\r\n\r\n                try { localStorage.setItem(getOnboardingStorageKey(onboardingUser.uid), \"true\"); } catch (_) {}\r\n                setSetupStatus(\"Setup saved. Opening dashboard...\", \"success\");\r\n                window.setTimeout(() => {\r\n                    firstSetupOverlay.classList.remove(\"is-visible\");\r\n                    firstSetupOverlay.setAttribute(\"aria-hidden\", \"true\");\r\n                }, 600);\r\n            } catch (error) {\r\n                console.error(\"First setup save error:\", error);\r\n                setSetupStatus(error.message || \"Setup save failed. Please try again.\", \"error\");\r\n                firstSetupSaveBtn.disabled = false;\r\n            }\r\n        });\r\n\r\n        onAuthStateChanged(auth, async (user) => {\r\n            if (user) {\r\n                userWelcome.classList.add('show');\r\n                loginSection.style.display = 'none';\r\n                renderCachedDashboardStats(user.uid);\r\n                const adminProfilePromise = loadAdminProfile(user);\r\n                // Keep the first interactive paint free of large collection reads.\r\n                // Fresh totals are loaded immediately after the browser gets a frame.\r\n                requestAnimationFrame(() => requestAnimationFrame(() => refreshDashboardStats(user.uid)));\r\n                const adminProfile = await adminProfilePromise;\r\n                await runFirstLoginOnboarding(user, adminProfile);\r\n            } else {\r\n                userWelcome.classList.remove('show');\r\n                loginSection.style.display = 'block';\r\n            }\r\n        });\r\n\r\n        window.loginWithGoogle = async () => {\r\n            try {\r\n                const loginBtn = document.querySelector('.btn-primary');\r\n                loginBtn.innerHTML = '<i class=\"fas fa-spinner fa-spin\"></i> Signing in…';\r\n                loginBtn.disabled = true;\r\n                await signInWithPopup(auth, provider);\r\n            } catch (error) {\r\n                console.error(\"Login error:\", error);\r\n                alert(\"Login failed: \" + error.message);\r\n                location.reload();\r\n            }\r\n        };\r\n\r\n        window.logout = async () => {\r\n            try {\r\n                const logoutBtn = document.querySelector('.btn-logout');\r\n                logoutBtn.innerHTML = '<i class=\"fas fa-spinner fa-spin\"></i> Logging out…';\r\n                logoutBtn.disabled = true;\r\n                await signOut(auth);\r\n                window.location.href = '#/index.html';\r\n            } catch (error) {\r\n                console.error(\"Logout error:\", error);\r\n                alert(\"Logout failed. Please try again.\");\r\n                location.reload();\r\n            }\r\n        };\r\n\r\n        function applyDashboardStats(stats) {\r\n            document.getElementById('totalStudents').textContent = Number(stats.students || 0).toLocaleString();\r\n            document.getElementById('totalClasses').textContent = Number(stats.classes || 0).toLocaleString();\r\n            document.getElementById('totalTeachers').textContent = Number(stats.teachers || 0).toLocaleString();\r\n            document.getElementById('totalFees').textContent = formatCurrency(stats.fees || 0);\r\n        }\r\n\r\n        function renderCachedDashboardStats(adminId) {\r\n            try {\r\n                const cached = JSON.parse(sessionStorage.getItem(dashboardStatsCachePrefix + adminId) || 'null');\r\n                if (cached && Date.now() - cached.savedAt < dashboardStatsCacheTtl) applyDashboardStats(cached);\r\n            } catch (_) {\r\n                // Stats cache is only an instant visual fallback.\r\n            }\r\n        }\r\n\r\n        function cacheDashboardStats(adminId, stats) {\r\n            try {\r\n                sessionStorage.setItem(dashboardStatsCachePrefix + adminId, JSON.stringify({ ...stats, savedAt: Date.now() }));\r\n            } catch (_) {}\r\n        }\r\n\r\n        async function refreshDashboardStats(adminId) {\r\n            try {\r\n                const [studentSnap, teacherSnap, feeSnap] = await Promise.all([\r\n                    getDocs(collection(db, \"schools\", adminId, \"students\")),\r\n                    getDocs(query(collection(db, \"users\"), where(\"role\", \"==\", \"teacher\"), where(\"adminId\", \"==\", adminId))),\r\n                    getDocs(collection(db, \"schools\", adminId, \"fees\"))\r\n                ]);\r\n\r\n                const sections = new Set();\r\n                studentSnap.forEach((docSnap) => {\r\n                    const student = docSnap.data();\r\n                    sections.add(`${student.class || \"\"}-${student.section || \"\"}`);\r\n                });\r\n\r\n                let collectedFees = 0;\r\n                feeSnap.forEach((docSnap) => {\r\n                    const fee = docSnap.data();\r\n                    collectedFees += Number(fee.totalCollectedAmount || fee.totalPaidAmount || fee.paidAmount || 0);\r\n                });\r\n\r\n                const stats = {\r\n                    students: studentSnap.size,\r\n                    classes: sections.size,\r\n                    teachers: teacherSnap.size,\r\n                    fees: collectedFees\r\n                };\r\n                applyDashboardStats(stats);\r\n                cacheDashboardStats(adminId, stats);\r\n            } catch (error) {\r\n                console.error('Dashboard stats refresh error:', error);\r\n            }\r\n        }\r\n    </script>\r\n    <script type=\"module\" src=\"admin-shell.js?v=admin-performance-20261024\"></script>\r\n    <script type=\"module\" src=\"access-control.js\"></script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-erp.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=admin-performance-20261024"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"src":"school-branding.js"},"text":""},{"attributes":{"type":"module"},"text":"\r\n        import { initializeApp } from \"./firebase-compat.js\";\r\n        import { \r\n            getAuth, \r\n            signInWithPopup, \r\n            GoogleAuthProvider, \r\n            signOut,\r\n            onAuthStateChanged\r\n        } from \"./firebase-compat.js\";\r\n        import { \r\n            getFirestore\r\n        } from \"./firebase-compat.js\";\r\n        import {\r\n            doc,\r\n            getDoc,\r\n            setDoc,\r\n            updateDoc,\r\n            collection,\r\n            getDocs,\r\n            query,\r\n            where,\r\n            serverTimestamp\r\n        } from \"./firebase-compat.js\";\r\n\r\n        const firebaseConfig = {\r\n            apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n            authDomain: \"schoolix-48107.firebaseapp.com\",\r\n            projectId: \"schoolix-48107\",\r\n            storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n            messagingSenderId: \"133937954491\",\r\n            appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n            measurementId: \"G-EG23XE5Q0Z\"\r\n        };\r\n\r\n        const app = initializeApp(firebaseConfig);\r\n        const auth = getAuth(app);\r\n        const db = getFirestore(app);\r\n        const provider = new GoogleAuthProvider();\r\n\r\n        const userWelcome = document.getElementById('userWelcome');\r\n        const userNameEl = document.getElementById('userName');\r\n        const userEmailEl = document.getElementById('userEmail');\r\n        const loginSection = document.getElementById('loginSection');\r\n        const schoolDisplayNameEl = document.getElementById('schoolDisplayName');\r\n        const schoolTaglineEl = document.getElementById('schoolTagline');\r\n        const firstLoginLaunch = document.getElementById('firstLoginLaunch');\r\n        const firstLoginLaunchCopy = document.getElementById('firstLoginLaunchCopy');\r\n        const firstLoginLaunchLogo = document.getElementById('firstLoginLaunchLogo');\r\n        const firstSetupOverlay = document.getElementById('firstSetupOverlay');\r\n        const firstSetupForm = document.getElementById('firstSetupForm');\r\n        const firstSetupStatus = document.getElementById('firstSetupStatus');\r\n        const firstSetupSaveBtn = document.getElementById('firstSetupSaveBtn');\r\n        const dashboardStatsCachePrefix = 'schoolix.dashboardStats.v1.';\r\n        const dashboardStatsCacheTtl = 5 * 60 * 1000;\r\n        let onboardingUser = null;\r\n        let onboardingProfile = null;\r\n\r\n        function formatCurrency(value) {\r\n            return `₹${Math.round(Number(value || 0)).toLocaleString('en-IN')}`;\r\n        }\r\n\r\n        async function loadAdminProfile(user) {\r\n            try {\r\n                const userSnap = await getDoc(doc(db, \"users\", user.uid));\r\n                if (!userSnap.exists()) return null;\r\n\r\n                const adminData = userSnap.data();\r\n                const schoolName = adminData.schoolName || window.SchoolBranding?.getSchoolName() || \"Schoolix\";\r\n                window.SchoolBranding?.persistSchoolLogo?.(adminData.logoUrl || adminData.schoolLogoUrl || \"\");\r\n                const adminName = adminData.name || user.displayName || user.email.split('@')[0];\r\n\r\n                window.SchoolBranding?.persistSchoolName(schoolName);\r\n                schoolDisplayNameEl.innerHTML = `<span>${schoolName}</span>`;\r\n                schoolTaglineEl.textContent = `Panel Owner: ${adminName}`;\r\n                userNameEl.textContent = adminName;\r\n                userEmailEl.textContent = `${schoolName} · ${user.email}`;\r\n\r\n                return { ...adminData, schoolName, adminName };\r\n            } catch (error) {\r\n                console.error(\"Admin profile load error:\", error);\r\n                return null;\r\n            }\r\n        }\r\n\r\n        function escapeAttribute(value) {\r\n            return String(value || \"\").replace(/&/g, \"&amp;\").replace(/\"/g, \"&quot;\").replace(/</g, \"&lt;\");\r\n        }\r\n\r\n        function suggestAcademicYears() {\r\n            const now = new Date();\r\n            const start = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;\r\n            return { start, end: start + 1 };\r\n        }\r\n\r\n        function getOnboardingStorageKey(userId) {\r\n            return `schoolix.adminOnboardingDone.${userId}`;\r\n        }\r\n\r\n        function needsFirstSetup(user, adminData) {\r\n            if (!user || String(adminData?.role || \"\").toLowerCase() !== \"admin\") return false;\r\n            if (adminData?.onboardingRequired !== true) return false;\r\n            try {\r\n                if (localStorage.getItem(getOnboardingStorageKey(user.uid)) === \"true\") return false;\r\n            } catch (_) {}\r\n            return adminData?.onboardingCompleted !== true && !adminData?.onboardingCompletedAt;\r\n        }\r\n\r\n        function primeSetupForm(adminData = {}) {\r\n            const years = suggestAcademicYears();\r\n            document.getElementById(\"setupStartYear\").value = adminData.setup?.sessionStartYear || years.start;\r\n            document.getElementById(\"setupEndYear\").value = adminData.setup?.sessionEndYear || years.end;\r\n            document.getElementById(\"setupSchoolPhone\").value = adminData.schoolPhone || adminData.phone || \"\";\r\n            document.getElementById(\"setupSchoolCode\").value = adminData.schoolCode || \"\";\r\n            document.getElementById(\"setupSchoolAddress\").value = adminData.schoolAddress || adminData.address || \"\";\r\n        }\r\n\r\n        async function runFirstLoginOnboarding(user, adminData) {\r\n            if (!needsFirstSetup(user, adminData)) return;\r\n            onboardingUser = user;\r\n            onboardingProfile = adminData || {};\r\n            primeSetupForm(onboardingProfile);\r\n            firstLoginLaunchCopy.textContent = `Preparing ${onboardingProfile.schoolName || \"your school\"} workspace...`;\r\n            const logoUrl = onboardingProfile.logoUrl || onboardingProfile.schoolLogoUrl || \"\";\r\n            firstLoginLaunchLogo.innerHTML = logoUrl\r\n                ? `<img src=\"${escapeAttribute(logoUrl)}\" alt=\"School logo\">`\r\n                : `<img src=\"schoolix-app-icon.svg\" alt=\"Schoolix\">`;\r\n            firstLoginLaunch.classList.add(\"is-visible\");\r\n            firstLoginLaunch.setAttribute(\"aria-hidden\", \"false\");\r\n            window.setTimeout(() => {\r\n                firstLoginLaunch.classList.remove(\"is-visible\");\r\n                firstLoginLaunch.setAttribute(\"aria-hidden\", \"true\");\r\n                firstSetupOverlay.classList.add(\"is-visible\");\r\n                firstSetupOverlay.setAttribute(\"aria-hidden\", \"false\");\r\n                document.getElementById(\"setupStartYear\")?.focus();\r\n            }, 2050);\r\n        }\r\n\r\n        function setSetupStatus(message, type = \"\") {\r\n            firstSetupStatus.textContent = message;\r\n            firstSetupStatus.className = `sx-setup-status ${type}`.trim();\r\n        }\r\n\r\n        firstSetupForm.addEventListener(\"submit\", async (event) => {\r\n            event.preventDefault();\r\n            if (!onboardingUser) return;\r\n            const startYear = Number(document.getElementById(\"setupStartYear\").value);\r\n            const endYear = Number(document.getElementById(\"setupEndYear\").value);\r\n            const schoolPhone = document.getElementById(\"setupSchoolPhone\").value.trim();\r\n            const schoolCode = document.getElementById(\"setupSchoolCode\").value.trim();\r\n            const schoolAddress = document.getElementById(\"setupSchoolAddress\").value.trim();\r\n            if (!startYear || !endYear || endYear <= startYear) {\r\n                setSetupStatus(\"Please enter a valid academic session.\", \"error\");\r\n                return;\r\n            }\r\n            const sessionLabel = `${startYear}-${endYear}`;\r\n            const sessionId = sessionLabel.replace(/[^0-9a-zA-Z]+/g, \"-\").replace(/^-+|-+$/g, \"\");\r\n            firstSetupSaveBtn.disabled = true;\r\n            setSetupStatus(\"Saving setup...\");\r\n            try {\r\n                await setDoc(doc(db, \"schools\", onboardingUser.uid, \"sessions\", sessionId), {\r\n                    startYear,\r\n                    endYear,\r\n                    session: sessionLabel,\r\n                    locked: false,\r\n                    classesLocked: false,\r\n                    createdAt: serverTimestamp(),\r\n                    createdBy: onboardingUser.uid,\r\n                    createdFrom: \"first-login-setup\"\r\n                }, { merge: true });\r\n\r\n                await setDoc(doc(db, \"schools\", onboardingUser.uid, \"settings\", \"activeSession\"), {\r\n                    sessionId,\r\n                    session: sessionLabel,\r\n                    sessionLabel,\r\n                    updatedAt: serverTimestamp(),\r\n                    updatedBy: onboardingUser.uid\r\n                }, { merge: true });\r\n\r\n                const setupPayload = {\r\n                    onboardingRequired: false,\r\n                    onboardingCompleted: true,\r\n                    onboardingCompletedAt: serverTimestamp(),\r\n                    setup: {\r\n                        sessionId,\r\n                        session: sessionLabel,\r\n                        sessionStartYear: startYear,\r\n                        sessionEndYear: endYear,\r\n                        completedAt: new Date().toISOString()\r\n                    },\r\n                    updatedAt: serverTimestamp()\r\n                };\r\n                if (schoolPhone) setupPayload.schoolPhone = schoolPhone;\r\n                if (schoolCode) setupPayload.schoolCode = schoolCode;\r\n                if (schoolAddress) setupPayload.schoolAddress = schoolAddress;\r\n\r\n                await Promise.all([\r\n                    updateDoc(doc(db, \"users\", onboardingUser.uid), setupPayload),\r\n                    setDoc(doc(db, \"schools\", onboardingUser.uid), setupPayload, { merge: true })\r\n                ]);\r\n\r\n                try { localStorage.setItem(getOnboardingStorageKey(onboardingUser.uid), \"true\"); } catch (_) {}\r\n                setSetupStatus(\"Setup saved. Opening dashboard...\", \"success\");\r\n                window.setTimeout(() => {\r\n                    firstSetupOverlay.classList.remove(\"is-visible\");\r\n                    firstSetupOverlay.setAttribute(\"aria-hidden\", \"true\");\r\n                }, 600);\r\n            } catch (error) {\r\n                console.error(\"First setup save error:\", error);\r\n                setSetupStatus(error.message || \"Setup save failed. Please try again.\", \"error\");\r\n                firstSetupSaveBtn.disabled = false;\r\n            }\r\n        });\r\n\r\n        onAuthStateChanged(auth, async (user) => {\r\n            if (user) {\r\n                userWelcome.classList.add('show');\r\n                loginSection.style.display = 'none';\r\n                renderCachedDashboardStats(user.uid);\r\n                const adminProfilePromise = loadAdminProfile(user);\r\n                // Keep the first interactive paint free of large collection reads.\r\n                // Fresh totals are loaded immediately after the browser gets a frame.\r\n                requestAnimationFrame(() => requestAnimationFrame(() => refreshDashboardStats(user.uid)));\r\n                const adminProfile = await adminProfilePromise;\r\n                await runFirstLoginOnboarding(user, adminProfile);\r\n            } else {\r\n                userWelcome.classList.remove('show');\r\n                loginSection.style.display = 'block';\r\n            }\r\n        });\r\n\r\n        window.loginWithGoogle = async () => {\r\n            try {\r\n                const loginBtn = document.querySelector('.btn-primary');\r\n                loginBtn.innerHTML = '<i class=\"fas fa-spinner fa-spin\"></i> Signing in…';\r\n                loginBtn.disabled = true;\r\n                await signInWithPopup(auth, provider);\r\n            } catch (error) {\r\n                console.error(\"Login error:\", error);\r\n                alert(\"Login failed: \" + error.message);\r\n                location.reload();\r\n            }\r\n        };\r\n\r\n        window.logout = async () => {\r\n            try {\r\n                const logoutBtn = document.querySelector('.btn-logout');\r\n                logoutBtn.innerHTML = '<i class=\"fas fa-spinner fa-spin\"></i> Logging out…';\r\n                logoutBtn.disabled = true;\r\n                await signOut(auth);\r\n                window.location.href = '#/index.html';\r\n            } catch (error) {\r\n                console.error(\"Logout error:\", error);\r\n                alert(\"Logout failed. Please try again.\");\r\n                location.reload();\r\n            }\r\n        };\r\n\r\n        function applyDashboardStats(stats) {\r\n            document.getElementById('totalStudents').textContent = Number(stats.students || 0).toLocaleString();\r\n            document.getElementById('totalClasses').textContent = Number(stats.classes || 0).toLocaleString();\r\n            document.getElementById('totalTeachers').textContent = Number(stats.teachers || 0).toLocaleString();\r\n            document.getElementById('totalFees').textContent = formatCurrency(stats.fees || 0);\r\n        }\r\n\r\n        function renderCachedDashboardStats(adminId) {\r\n            try {\r\n                const cached = JSON.parse(sessionStorage.getItem(dashboardStatsCachePrefix + adminId) || 'null');\r\n                if (cached && Date.now() - cached.savedAt < dashboardStatsCacheTtl) applyDashboardStats(cached);\r\n            } catch (_) {\r\n                // Stats cache is only an instant visual fallback.\r\n            }\r\n        }\r\n\r\n        function cacheDashboardStats(adminId, stats) {\r\n            try {\r\n                sessionStorage.setItem(dashboardStatsCachePrefix + adminId, JSON.stringify({ ...stats, savedAt: Date.now() }));\r\n            } catch (_) {}\r\n        }\r\n\r\n        async function refreshDashboardStats(adminId) {\r\n            try {\r\n                const [studentSnap, teacherSnap, feeSnap] = await Promise.all([\r\n                    getDocs(collection(db, \"schools\", adminId, \"students\")),\r\n                    getDocs(query(collection(db, \"users\"), where(\"role\", \"==\", \"teacher\"), where(\"adminId\", \"==\", adminId))),\r\n                    getDocs(collection(db, \"schools\", adminId, \"fees\"))\r\n                ]);\r\n\r\n                const sections = new Set();\r\n                studentSnap.forEach((docSnap) => {\r\n                    const student = docSnap.data();\r\n                    sections.add(`${student.class || \"\"}-${student.section || \"\"}`);\r\n                });\r\n\r\n                let collectedFees = 0;\r\n                feeSnap.forEach((docSnap) => {\r\n                    const fee = docSnap.data();\r\n                    collectedFees += Number(fee.totalCollectedAmount || fee.totalPaidAmount || fee.paidAmount || 0);\r\n                });\r\n\r\n                const stats = {\r\n                    students: studentSnap.size,\r\n                    classes: sections.size,\r\n                    teachers: teacherSnap.size,\r\n                    fees: collectedFees\r\n                };\r\n                applyDashboardStats(stats);\r\n                cacheDashboardStats(adminId, stats);\r\n            } catch (error) {\r\n                console.error('Dashboard stats refresh error:', error);\r\n            }\r\n        }\r\n    "},{"attributes":{"type":"module","src":"admin-shell.js?v=admin-performance-20261024"},"text":""},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""}]};
